% =========================================================================
% run_open_loop_validation.m
%
% Validates the trained DNN-Koopman model (dim=30) against TruckMaker
% ground truth, for BOTH paper scenarios:
%
%   Scenario 1 (deceleration):  Fx = -1000 N,        delta = 0
%   Scenario 2 (lane-change):   Fx = 5000*sin(t)+1000, delta = 5*sin(t)
%
% Both start from x0 = [25; 0; 0] (vx, vy, omega), run for N=400 steps
% at Ts=0.01s (4 seconds total), matching the paper's Remark 3 window.
%
% Requires:
%   - mpc_design_data_dim30.mat  (exported by export_to_matlab.py)
%   - koopman_encoder.m           (on the MATLAB path)
%   - scenario_1.csv, scenario_2.csv  (logged from the Simulink open-loop
%     test rig -- see chat for the model setup)
% =========================================================================

clear; clc;

%% ========================================================================
% LOAD TRAINED MODEL
% ========================================================================

load('G:\Control-Systems\DNN\models\dim_30\mpc_design_data_dim30.mat');   % adjust path if needed

% Cast Koopman matrices to double (per established project practice --
% DNN weights train in single/float32, must cast to double on load to
% avoid MATLAB's type-promotion contamination bug)
A = double(A_l);
B = double(B_l);
C = double(C_l);

x_mean = double(x_mean); x_std = double(x_std);
u_mean = double(u_mean); u_std = double(u_std);
Ts_loaded = double(Ts);

% Build W/b cell arrays generically -- works regardless of how many
% layers were actually saved (see koopman_encoder.m docstring)
n_layers = 0;
while exist(sprintf('W%d', n_layers+1), 'var')
    n_layers = n_layers + 1;
end

W = cell(1, n_layers);
b = cell(1, n_layers);
for k = 1:n_layers
    W{k} = double(eval(sprintf('W%d', k)));
    b{k} = double(eval(sprintf('b%d', k)));
end

fprintf('Loaded model: %d encoder layers, lifting_dim=%d\n', n_layers, double(lifting_dim)); %[output:4ee97d83]


%% ========================================================================
% COMMON TEST SETTINGS
% ========================================================================

N  = 400;                  % number of prediction steps
Ts = 0.01;                  % must match training/logging sample time
t_vec = (0:N-1)' * Ts;      % time vector for building input sequences

x0 = [25; 0; 0];            % initial state, both scenarios (paper's x0)

checkpoints = [10, 80, 200, 400];


%% ========================================================================
% BUILD BOTH SCENARIOS' INPUT SEQUENCES
% ========================================================================

% --- Scenario 1: deceleration -------------------------------------------
Fx_seq_1    = -1000 * ones(N,1);
delta_seq_1 = zeros(N,1);
%%

% --- Scenario 2: lane-change ---------------------------------------------
% NOTE: paper states delta = 5*sin(t) in RADIANS, which is physically
% unrealistic (~286 deg peak) and inconsistent with the paper's own
% +/-10 deg steering limit elsewhere. Commanded here EXACTLY as stated;
% TruckMaker's real saturation block (+/-0.1745 rad) will clip this in
% the ground-truth run, so expect the MATLAB (unsaturated, linear model)
% prediction to diverge from the TruckMaker (saturated, real) result for
% this reason -- that is an expected, explainable discrepancy, not a bug.
Fx_seq_2    = 5000*sin(t_vec) + 1000;
delta_seq_2 = 5*sin(t_vec)*pi/180;


%% ========================================================================
% RUN OPEN-LOOP PREDICTION FOR ONE SCENARIO (reusable local function)
% ========================================================================

function x_pred = predict_scenario(x0, Fx_seq, delta_seq, N, A, B, C, ...
    W, b, x_mean, x_std, u_mean, u_std)

    x0_norm = ((x0' - x_mean) ./ x_std)';        % 3x1
    phi0 = koopman_encoder(x0_norm, W, b);
    z = [x0_norm; phi0];

    x_pred = zeros(3, N+1);
    x_pred(:,1) = x0;

    for k = 1:N
        u_phys = [Fx_seq(k); delta_seq(k)];
        u_norm = ((u_phys' - u_mean) ./ u_std)';

        z = A*z + B*u_norm;
        x_hat_norm = C*z;
        x_hat = (x_hat_norm' .* x_std) + x_mean;
        x_pred(:,k+1) = x_hat';
    end
end


%% ========================================================================
% RUN BOTH SCENARIOS
% ========================================================================

fprintf('\nRunning Scenario 1 (deceleration) prediction...\n'); %[output:82d17521]
x_pred_1 = predict_scenario(x0, Fx_seq_1, delta_seq_1, N, A, B, C, ...
    W, b, x_mean, x_std, u_mean, u_std);

fprintf('Running Scenario 2 (lane-change) prediction...\n'); %[output:486276e6]
x_pred_2 = predict_scenario(x0, Fx_seq_2, delta_seq_2, N, A, B, C, ...
    W, b, x_mean, x_std, u_mean, u_std);


%% ========================================================================
% IMPORT GROUND-TRUTH CSVs (TruckMaker logged data)
%
% Handles the same column-shift issue confirmed earlier for this
% project's exported CSVs -- adjust DataLines/columns if your export
% format has since changed.
% ========================================================================

function x_true = import_ground_truth(csv_path)
    opts = detectImportOptions(csv_path);
    T = readtable(csv_path, opts);

    % Expect columns: time, vx, vy, omega (adjust names below if your
    % Simulink logging used different To Workspace variable names)
    x_true = [T.vx'; T.vy'; T.YawRate'];
end

fprintf('\nImporting ground truth CSVs...\n'); %[output:40eadc88]
x_true_1 = import_ground_truth('G:\Control-Systems\output\scenario_1\simulation_data.csv');
x_true_2 = import_ground_truth('G:\Control-Systems\output\scenario_2\simulation_data.csv');

fprintf('Scenario 1 x_true(:,1) [should be ~25,0,0]:\n'); disp(x_true_1(:,1)); %[output:7f782373]
fprintf('Scenario 2 x_true(:,1) [should be ~25,0,0]:\n'); disp(x_true_2(:,1)); %[output:82cb1af3]


%% ========================================================================
% RMSE COMPARISON, PER SCENARIO, AT PAPER'S CHECKPOINTS
% ========================================================================

function print_rmse_table(scenario_name, x_pred, x_true, checkpoints, paper_row)
    fprintf('\n--- %s ---\n', scenario_name);
    fprintf('%-12s', 'Timestep');
    for cp = checkpoints, fprintf('%-10d', cp); end
    fprintf('\n%-12s', 'RMSE (%)');

    for i = 1:length(checkpoints)
        cp = min(checkpoints(i), size(x_pred,2)-1) + 1;
        err = x_pred(:,1:cp) - x_true(:,1:cp);
        truev = x_true(:,1:cp);
        rmse = sqrt(sum(vecnorm(err).^2)) / sqrt(sum(vecnorm(truev).^2)) * 100;
        fprintf('%-10.2f', rmse);
    end
    fprintf('\n%-12s', 'Paper-30');
    for i = 1:length(paper_row), fprintf('%-10.2f', paper_row(i)); end
    fprintf('\n');
end

% Paper's Koopman-30 rows, for direct comparison (Table I / Table II)
paper_scenario1 = [0.06, 0.13, 0.26, 0.39];
paper_scenario2 = [0.11, 1.00, 1.50, 1.51];

print_rmse_table('SCENARIO 1: Deceleration', x_pred_1, x_true_1, checkpoints, paper_scenario1); %[output:4d540a5d]
print_rmse_table('SCENARIO 2: Lane-change',  x_pred_2, x_true_2, checkpoints, paper_scenario2); %[output:5072409e]


%% ========================================================================
% PLOTS
% ========================================================================

t_plot = 0:Ts:(N*Ts);

figure('Name','Scenario 1: Deceleration'); %[output:42d059d2]

subplot(3,1,1); %[output:42d059d2]
plot(t_plot, x_true_1(1,:), 'r-', ... %[output:42d059d2]
     t_plot, x_pred_1(1,:), 'g--', 'LineWidth', 1.5); %[output:42d059d2]
legend('True','Predicted (dim=30)'); %[output:42d059d2]
ylabel('v_x (m/s)'); %[output:42d059d2]
title('Scenario 1: Deceleration'); %[output:42d059d2]
grid on; %[output:42d059d2]

subplot(3,1,2); %[output:42d059d2]
plot(t_plot, x_true_1(2,:), 'r-', ... %[output:42d059d2]
     t_plot, x_pred_1(2,:), 'g--', 'LineWidth', 1.5); %[output:42d059d2]
legend('True','Predicted (dim=30)'); %[output:42d059d2]
ylabel('v_y (m/s)'); %[output:42d059d2]
grid on; %[output:42d059d2]

subplot(3,1,3); %[output:42d059d2]
plot(t_plot, x_true_1(3,:), 'r-', ... %[output:42d059d2]
     t_plot, x_pred_1(3,:), 'g--', 'LineWidth', 1.5); %[output:42d059d2]
legend('True','Predicted (dim=30)'); %[output:42d059d2]
ylabel('\omega (rad/s)'); %[output:42d059d2]
xlabel('Time (s)'); %[output:42d059d2]
grid on; %[output:42d059d2]

figure('Name','Scenario 2: Lane-change'); %[output:0c9fc168]

subplot(3,1,1); %[output:0c9fc168]
plot(t_plot, x_true_2(1,:), 'r-', ... %[output:0c9fc168]
     t_plot, x_pred_2(1,:), 'g--', 'LineWidth', 1.5); %[output:0c9fc168]
legend('True','Predicted (dim=30)'); %[output:0c9fc168]
ylabel('v_x (m/s)'); %[output:0c9fc168]
title('Scenario 2: Lane-change'); %[output:0c9fc168]
grid on; %[output:0c9fc168]

subplot(3,1,2); %[output:0c9fc168]
plot(t_plot, x_true_2(2,:), 'r-', ... %[output:0c9fc168]
     t_plot, x_pred_2(2,:), 'g--', 'LineWidth', 1.5); %[output:0c9fc168]
legend('True','Predicted (dim=30)'); %[output:0c9fc168]
ylabel('v_y (m/s)'); %[output:0c9fc168]
grid on; %[output:0c9fc168]

subplot(3,1,3); %[output:0c9fc168]
plot(t_plot, x_true_2(3,:), 'r-', ... %[output:0c9fc168]
     t_plot, x_pred_2(3,:), 'g--', 'LineWidth', 1.5); %[output:0c9fc168]
legend('True','Predicted (dim=30)'); %[output:0c9fc168]
ylabel('\omega (rad/s)'); %[output:0c9fc168]
xlabel('Time (s)'); %[output:0c9fc168]
grid on; %[output:0c9fc168]
fprintf('\nDone. Review plots and RMSE tables above.\n'); %[output:86644f25]

